public EventMessage decode(ParsableByteArray emsgData){
  String schemeIdUri=Assertions.checkNotNull(emsgData.readNullTerminatedString());
  String value=Assertions.checkNotNull(emsgData.readNullTerminatedString());
  long durationMs=emsgData.readUnsignedInt();
  long id=emsgData.readUnsignedInt();
  byte[] messageData;
  try {
    messageData = Arrays.copyOfRange(emsgData.data, emsgData.getPosition(), emsgData.limit());
  } catch (NullPointerException e) {
    // Handle the case where emsgData.data is null
    messageData = new byte[0];
  }
  return new EventMessage(schemeIdUri, value, durationMs, id, messageData);
}
